const identifyTaskDB=[{"s":"Distinción entre quién habla y quién ve, con los tres grados de cuánto sabe el narrador.","type":"Voz y focalización (Genette, 1972)"},{"s":"Un narrador puede equivocarse o mentir; se mide contra el autor implícito.","type":"El narrador no fiable (Booth, 1961)"},{"s":"Distingue quién focaliza de qué se focaliza, para los casos borrosos.","type":"El focalizador y el focalizado (Bal, 1985)"},{"s":"Tipología de narrador autorial, en primera persona, y figural.","type":"Las situaciones narrativas (Stanzel, 1979)"},{"s":"Funde la voz del narrador con la mente del personaje, sin comillas.","type":"El estilo indirecto libre (Bally, 1912)"},{"s":"Contar la historia a través de la conciencia de un solo personaje reflector.","type":"La inteligencia central (James, 1907-1909)"},{"s":"El cronista al que el narrador del Quijote atribuye la historia, y del que desconfía.","type":"Cide Hamete Benengeli"},{"s":"Herramienta de esta etapa con tres casillas: quién habla, cuánto sabe, cuánto se le cree.","type":"La ficha del narrador"},{"s":"Modelar lo que otra mente sabe y cree, distinto de lo que uno mismo sabe.","type":"La teoría de la mente (Premack y Woodruff, 1978)"},{"s":"Cómo se mide si un niño entiende que otro puede creer algo falso.","type":"La tarea de la falsa creencia (Wimmer y Perner, 1983)"}];
const classifyTaskDB=[{"w":"Voz y focalización","gen":"Taxonomía","n":"Separa quién habla de quién ve","g":"Análisis estructuralista","t":"Genette, 1972"},{"w":"El narrador no fiable","gen":"Concepto crítico","n":"Se equivoca o miente, medido contra el autor implícito","g":"Teoría crítica reformulada","t":"Booth, 1961"},{"w":"El focalizador y el focalizado","gen":"Taxonomía","n":"Quién ve y qué se ve","g":"Análisis estructuralista","t":"Bal, 1985"},{"w":"Las situaciones narrativas","gen":"Tipología","n":"Autorial, en primera persona, figural","g":"Tipología de autor","t":"Stanzel, 1979"},{"w":"El estilo indirecto libre","gen":"Término técnico","n":"Funde voz de narrador y personaje","g":"Lingüística","t":"Bally, 1912"},{"w":"La inteligencia central","gen":"Técnica declarada","n":"Un solo personaje reflector","g":"Prefacios de novelista","t":"James, 1907-1909"},{"w":"Cide Hamete Benengeli","gen":"Caso comprobable","n":"Fuente citada y a la vez desconfiada","g":"Dispositivo narrativo real","t":"Quijote, 1605"},{"w":"La teoría de la mente","gen":"Hallazgo","n":"Modelar lo que otra mente sabe","g":"Psicología cognitiva","t":"Premack y Woodruff, 1978"},{"w":"La tarea de la falsa creencia","gen":"Hallazgo","n":"Mide si un niño entiende una creencia falsa ajena","g":"Psicología del desarrollo","t":"Wimmer y Perner, 1983"},{"w":"La ficha del narrador","gen":"Herramienta práctica","n":"Quién habla, cuánto sabe, cuánto se le cree","g":"Herramienta de esta casa","t":"Etapa 6"}];
const completeTaskDB=[{"s":"Genette separa la voz de la ___.","opts":["focalización","fábula","trama"],"ans":"focalización"},{"s":"Booth mide al narrador contra el autor ___.","opts":["implícito","real","editor"],"ans":"implícito"},{"s":"Bal distingue el focalizador del ___.","opts":["focalizado","narrador","lector"],"ans":"focalizado"},{"s":"Stanzel describe tres ___ narrativas.","opts":["situaciones","escenas","fábulas"],"ans":"situaciones"},{"s":"Bally acuñó el estilo indirecto ___ en 1912.","opts":["libre","directo","oculto"],"ans":"libre"},{"s":"James llamó a su técnica la inteligencia ___.","opts":["central","lateral","externa"],"ans":"central"},{"s":"El Quijote desconfía de su fuente, Cide Hamete ___.","opts":["Benengeli","Alfayate","Bercebú"],"ans":"Benengeli"},{"s":"La ficha del narrador tiene tres ___.","opts":["casillas","páginas","autores"],"ans":"casillas"}];
const explainQuestions=[{"q":"Explica la distinción entre la voz y la focalización según Gérard Genette (1972), y por qué son dos preguntas distintas.","ans":"Gérard Genette, en «Figures III» (1972), separó dos preguntas que la costumbre solía mezclar: la voz, quién habla (¿primera, segunda o tercera persona? ¿un personaje o una voz de fuera?), y la focalización, cuánto sabe el narrador respecto a los personajes. Una voz en primera persona puede estar focalizada desde fuera, sin entender del todo lo que narra; una tercera persona puede saber solo lo que un personaje sabe. Confundir las dos preguntas es el error de fondo que esta etapa desarma: la persona gramatical con la que alguien habla no dice nada, por sí sola, sobre cuánto sabe."},{"q":"Explica el concepto del narrador no fiable y el autor implícito, de Wayne Booth (1961).","ans":"Wayne Booth, en «The Rhetoric of Fiction» (1961), sostiene que un narrador puede equivocarse o mentir, y que su fiabilidad no se mide contra la realidad objetiva, sino contra el autor implícito: la imagen del autor que el propio texto proyecta, distinta del autor real y del narrador. Cuando los valores y la percepción del narrador coinciden con los del autor implícito, se le considera fiable; cuando hay señales de que se equivoca, miente o no entiende lo que cuenta, se le considera no fiable. Es un concepto crítico que, después, Ansgar Nünning reformuló del lado del lector, no solo del autor implícito."},{"q":"Explica por qué «narrador omnisciente» no es lo mismo que «tercera persona».","ans":"La omnisciencia es cuánto SABE el narrador (lo que Genette, 1972, llama focalización cero), no la persona gramatical con la que habla. Un narrador puede escribir en tercera persona y saber solo lo que un personaje sabe, con focalización interna, sin ninguna omnisciencia. Y un narrador en primera persona puede, dentro de la ficción, tener acceso a información que ese personaje no podría tener por sí solo. Vender la tercera persona como sinónimo de objetividad o de saberlo todo es exactamente la confusión que esta etapa enseña a desarmar."},{"q":"Explica el refinamiento que Mieke Bal (1985) le hace al sistema de Genette.","ans":"Mieke Bal, en «Narratología» (1985), hace la crítica más seria al sistema de Genette: señala que sus tres grados de focalización dejan casos borrosos, donde no queda claro si la focalización es interna o externa. Para resolverlo, distingue al focalizador, quien ve, del focalizado, aquello que se ve: dos elementos que Genette trataba juntos. Sigue siendo teoría de análisis, no una receta de qué elegir al escribir, pero resuelve varios de los casos que el sistema original dejaba sin clasificar."},{"q":"Explica el caso de Cide Hamete Benengeli en el Quijote, y por qué es la fila con caso comprobable de esta etapa.","ans":"En el «Quijote» (1605 y 1615), el narrador atribuye la «historia verdadera» a un cronista árabe, Cide Hamete Benengeli, y a la vez, en varios pasajes, lo llama mentiroso y desconfía de su fuente. Es un caso real, fechado y comprobable, publicado cuatro siglos antes de que Wayne Booth le pusiera nombre al concepto del narrador no fiable, en 1961. El caso muestra que citar una fuente y declarar la desconfianza en ella al mismo tiempo, en vez de fingir una certeza que no existe, es una técnica narrativa mucho más vieja que su propia teoría."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> El cronista al que el narrador del Quijote atribuye la historia, y del que desconfía. → <span style="color:var(--jade);font-weight:700;">Cide Hamete Benengeli</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
