const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda herramienta se cite con autor y año.","a":true},{"q":"«Punto de vista» es una sola pregunta: quién habla.","a":false},{"q":"Gérard Genette publicó «Figures III» en 1972.","a":true},{"q":"Un narrador omnisciente es, por definición, el mismo que un narrador en tercera persona.","a":false},{"q":"Wayne Booth distingue el autor implícito del autor real y del narrador.","a":true},{"q":"Mieke Bal, en 1985, refinó la focalización de Genette distinguiendo el focalizador del focalizado.","a":true},{"q":"Franz Stanzel describe tres situaciones narrativas: autorial, en primera persona y figural.","a":true},{"q":"El estilo indirecto libre lo acuñó Charles Bally en 1912.","a":true},{"q":"Henry James llamaba a su técnica la «inteligencia central», en los prefacios de 1907 a 1909.","a":true},{"q":"El narrador del Quijote confía por completo en su fuente, Cide Hamete Benengeli.","a":false},{"q":"Premack y Woodruff acuñaron el término «teoría de la mente» en 1978.","a":true},{"q":"La tarea de la falsa creencia, de Wimmer y Perner, es de 1983.","a":true},{"q":"El estudio de Kidd y Castano (2013) tuvo una réplica exitosa, sin ninguna objeción.","a":false},{"q":"La ficha del narrador tiene tres casillas: quién habla, cuánto sabe y cuánto se le puede creer.","a":true},{"q":"La focalización cero significa que el narrador sabe menos que los personajes.","a":false}];
const evalMCBank=[{"q":"¿Qué separa Gérard Genette en «Figures III» (1972)?","o":["a) La persona y el tiempo verbal","b) Mostrar y contar","c) La fábula y la trama","d) Quién habla y quién ve"],"a":3},{"q":"¿Qué mide la focalización, según Genette (1972)?","o":["a) La persona gramatical","b) Cuánto sabe el narrador respecto a los personajes","c) El tono del narrador","d) La duración de la escena"],"a":1},{"q":"¿Cuáles son los tres grados de focalización de Genette?","o":["a) Cero, interna, externa","b) Pasado, presente, futuro","c) Fiable, dudoso, mentiroso","d) Autorial, personal, figural"],"a":0},{"q":"¿Qué propone Wayne Booth en «The Rhetoric of Fiction» (1961)?","o":["a) El concepto del narrador no fiable y el autor implícito","b) Que el narrador siempre es fiable","c) Los tres grados de focalización","d) El estilo indirecto libre"],"a":0},{"q":"¿Qué es el autor implícito, según Booth (1961)?","o":["a) El autor real, con otro nombre","b) La imagen del autor que el texto proyecta, distinta del real y del narrador","c) El narrador, con otro nombre","d) El editor del libro"],"a":1},{"q":"¿Qué aporta Mieke Bal en «Narratología» (1985)?","o":["a) Distingue el focalizador del focalizado, refinando a Genette","b) Inventa la focalización","c) Traduce a Booth","d) Niega que exista la focalización"],"a":0},{"q":"¿Qué son las «situaciones narrativas» de Franz Stanzel (1979)?","o":["a) Una tipología: narrador autorial, en primera persona y figural","b) Los grados de focalización","c) El estilo indirecto libre","d) El autor implícito"],"a":0},{"q":"¿Qué es el estilo indirecto libre, término de Charles Bally (1912)?","o":["a) El diálogo con comillas","b) Funde la voz del narrador con la mente del personaje, sin comillas ni «pensó que»","c) El resumen de una escena","d) La fábula de una novela"],"a":1},{"q":"¿Qué es la «inteligencia central», de Henry James (prefacios, 1907-1909)?","o":["a) Un narrador que lo sabe todo","b) El estilo indirecto libre","c) El autor implícito","d) Contar la historia a través de la conciencia de un solo personaje reflector"],"a":3},{"q":"¿A quién atribuye el narrador del Quijote (1605 y 1615) la historia, mientras desconfía de él?","o":["a) A Percy Lubbock","b) A Wayne Booth","c) A Cide Hamete Benengeli","d) A su propio hermano"],"a":2},{"q":"¿Qué acuñaron Premack y Woodruff en 1978?","o":["a) La tarea de la falsa creencia","b) La focalización cero","c) El término «teoría de la mente»","d) El autor implícito"],"a":2},{"q":"¿Qué mide la tarea de la falsa creencia, de Wimmer y Perner (1983)?","o":["a) La fiabilidad de un narrador","b) El estilo indirecto libre","c) Si un niño entiende que otro puede creer algo falso","d) Los grados de focalización"],"a":2},{"q":"¿Qué encontraron Kidd y Castano en 2013, y qué pasó con Panero y colegas en 2016?","o":["a) Kidd y Castano no publicaron nada, y Panero lo inventó","b) Panero confirmó el hallazgo sin ninguna duda","c) Ninguno de los dos estudió teoría de la mente","d) Kidd y Castano hallaron que la ficción literaria mejora la teoría de la mente; Panero y colegas no lograron replicarlo"],"a":3},{"q":"¿Cuáles son las tres casillas de la ficha del narrador, la herramienta de esta etapa?","o":["a) Título, fecha y lugar","b) Quién habla, cuánto sabe y cuánto se le puede creer","c) Presupuesto, elenco y locación","d) Género, tono y duración"],"a":1},{"q":"¿Por qué «narrador omnisciente» no es lo mismo que «tercera persona»?","o":["a) Porque la tercera persona no existe","b) Porque solo Cide Hamete es omnisciente","c) Porque la omnisciencia es cuánto SABE el narrador, no la persona gramatical","d) Porque Booth lo prohibió"],"a":2}];
const evalCPBank=[{"q":"Gérard Genette separa quién habla de quién ___.","a":"ve"},{"q":"Genette publicó «Figures III» en ___.","a":"1972"},{"q":"Wayne Booth publicó «The Rhetoric of Fiction» en ___.","a":"1961"},{"q":"El concepto del narrador no fiable se mide contra el autor ___.","a":"implícito"},{"q":"Mieke Bal publicó «Narratología» en ___.","a":"1985"},{"q":"Bal distingue el focalizador del ___.","a":"focalizado"},{"q":"Franz Stanzel publicó su teoría de la narración en ___.","a":"1979"},{"q":"Charles Bally acuñó el término estilo indirecto ___ en 1912.","a":"libre"},{"q":"Henry James llamó a su técnica la inteligencia ___.","a":"central"},{"q":"El narrador del Quijote desconfía de su fuente, Cide Hamete ___.","a":"Benengeli"},{"q":"Premack y Woodruff acuñaron el término teoría de la ___ en 1978.","a":"mente"},{"q":"Wimmer y Perner publicaron la tarea de la falsa creencia en ___.","a":"1983"},{"q":"Kidd y Castano publicaron su estudio en la revista ___ en 2013.","a":"Science"},{"q":"La réplica de Kidd y Castano no tuvo éxito en el estudio de Panero y colegas, de ___.","a":"2016"},{"q":"La ficha del narrador tiene tres ___.","a":"casillas"}];
const evalPRBank=[{"term":"La voz","def":"Quién habla: primera, segunda o tercera persona, personaje o voz de fuera"},{"term":"La focalización","def":"Cuánto sabe el narrador respecto a los personajes (Genette, 1972)"},{"term":"Focalización cero","def":"El narrador sabe más que los personajes (omnisciente)"},{"term":"Focalización interna","def":"El narrador sabe lo mismo que un personaje"},{"term":"Focalización externa","def":"El narrador sabe menos, solo lo observable desde fuera"},{"term":"El narrador no fiable","def":"Concepto de Wayne Booth (1961): un narrador que puede equivocarse o mentir"},{"term":"El autor implícito","def":"La imagen del autor que el texto proyecta, distinta del autor real y del narrador (Booth, 1961)"},{"term":"El focalizador y el focalizado","def":"El refinamiento de Mieke Bal (1985): quién ve, y qué se ve"},{"term":"Las situaciones narrativas","def":"Tipología de Franz Stanzel (1979): autorial, en primera persona y figural"},{"term":"El estilo indirecto libre","def":"Término de Charles Bally (1912): funde la voz del narrador con la del personaje"},{"term":"La inteligencia central","def":"La técnica de Henry James (1907-1909): contar a través de un solo personaje reflector"},{"term":"Cide Hamete Benengeli","def":"El cronista al que el narrador del Quijote atribuye la historia, y del que desconfía"},{"term":"La teoría de la mente","def":"Modelar lo que otra mente sabe y cree (Premack y Woodruff, 1978)"},{"term":"La tarea de la falsa creencia","def":"Cómo se mide si un niño entiende que otro puede creer algo falso (Wimmer y Perner, 1983)"},{"term":"La ficha del narrador","def":"La herramienta de esta etapa: quién habla, cuánto sabe, cuánto se le puede creer"}];
function genEval(){sfx('click');_evalFormaSelector();const _selF=document.getElementById('evalFormaSel');if(_selF&&parseInt(_selF.value,10))evalFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_selF.value,10)));const cf=evalFormNum;const rng=_evalRng(cf);window._currentEvalForm=cf;evalFormNum=(evalFormNum%EVAL_FORMAS)+1;_evalFormaSelector();saveProgress();document.getElementById('eval-screen-title').textContent=`🎓 Evaluación Final · Forma ${cf} · La voz y el punto de vista · Ruta del Hilo que Tira`;evalAnsVisible=false;const out=document.getElementById('evalOut');out.innerHTML='';const bar=document.createElement('div');bar.className='eval-score-bar';bar.innerHTML=`<div><div class="esb-title">📊 Distribución de puntaje · 100 puntos</div><div class="esb-dist">Cada sección vale 25 puntos (5 preguntas × 5 pts)</div></div><div style="display:flex;gap:0.4rem;flex-wrap:wrap;"><span class="eval-score-pill esp-cp">Completar 25 pts</span><span class="eval-score-pill esp-tf">V/F 25 pts</span><span class="eval-score-pill esp-mc">Selección 25 pts</span><span class="eval-score-pill esp-pr">Pareados 25 pts</span></div>`;out.appendChild(bar);const cpItems=_pickF(evalCPBank,5,rng);const s1=document.createElement('div');s1.innerHTML='<div class="eval-section-title">I. Completar el espacio <span class="eval-pts">25 pts · 5 pts c/u</span></div>';cpItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='cp';d.dataset.evalIndex=i;const qHtml=item.q.replace('___',`<input class="eval-cp-input" type="text" data-cp="${i}" autocomplete="off">`);d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+1}</span><span class="eval-q-text">${qHtml}</span></div><div class="eval-answer">${item.a}</div><div class="eval-item-feedback" id="evalFbCp${i}" aria-live="polite"></div>`;s1.appendChild(d);});out.appendChild(s1);const tfItems=_pickF(evalTFBank,5,rng);const s2=document.createElement('div');s2.innerHTML='<div class="eval-section-title">II. Verdadero o Falso <span class="eval-pts">25 pts · 5 pts c/u</span></div>';tfItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='tf';d.dataset.evalIndex=i;d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+6}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-tf-opts"><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="true"> Verdadero</label><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="false"> Falso</label></div><div class="eval-answer">${item.a?'Verdadero':'Falso'}</div><div class="eval-item-feedback" id="evalFbTf${i}" aria-live="polite"></div>`;s2.appendChild(d);});out.appendChild(s2);const mcItems=_pickF(evalMCBank,5,rng);const s3=document.createElement('div');s3.innerHTML='<div class="eval-section-title">III. Selección Múltiple <span class="eval-pts">25 pts · 5 pts c/u</span></div>';mcItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='mc';d.dataset.evalIndex=i;const optsHtml=item.o.map((op,oi)=>`<label class="eval-mc-opt"><input type="radio" name="mc${i}" value="${oi}"> ${op}</label>`).join('');d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+11}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-mc-opts">${optsHtml}</div><div class="eval-answer">${item.o[item.a]}</div><div class="eval-item-feedback" id="evalFbMc${i}" aria-live="polite"></div>`;s3.appendChild(d);});out.appendChild(s3);const prItems=_pickF(evalPRBank,5,rng);let shuffledDefs=_shuffleF(prItems,rng);let _prTries=0;while(shuffledDefs.some((df,ix)=>df.def===prItems[ix].def)&&_prTries<20){shuffledDefs=_shuffleF(shuffledDefs,rng);_prTries++;}const letters=['A','B','C','D','E'];const s4=document.createElement('div');s4.innerHTML='<div class="eval-section-title">IV. Términos Pareados <span class="eval-pts">25 pts · 5 pts c/u</span></div>';const matchCard=document.createElement('div');matchCard.className='eval-item';let colLeft='<div class="eval-match-col"><h4>📌 Términos</h4>';prItems.forEach((item,i)=>{colLeft+=`<div class="eval-match-item"><span class="eval-match-letter">${i+16}.</span> <select class="eval-match-select" data-pr="${i}" aria-label="Respuesta pareada ${i+16}"><option value="">?</option>${letters.map(l=>`<option value="${l}">${l}</option>`).join('')}</select> ${item.term}</div>`;});colLeft+='</div>';let colRight='<div class="eval-match-col"><h4>🔑 Definiciones</h4>';shuffledDefs.forEach((item,i)=>{colRight+=`<div class="eval-match-item"><span class="eval-match-letter">${letters[i]}.</span> ${item.def}</div>`;});colRight+='</div>';const ansKey=prItems.map((item,i)=>{const letter=letters[shuffledDefs.findIndex(d=>d.def===item.def)];return`${i+16}→${letter}`;}).join(' · ');matchCard.innerHTML=`<div class="eval-match-grid">${colLeft}${colRight}</div><div class="eval-answer" style="display:none;">${ansKey}</div><div class="eval-item-feedback" id="evalFbPr" aria-live="polite"></div>`;s4.appendChild(matchCard);out.appendChild(s4);window._evalPrintData={tf:tfItems,mc:mcItems,cp:cpItems,pr:{terms:prItems,shuffledDefs,letters}};const autoPanel=document.createElement('div');autoPanel.id='evalAutoResult';autoPanel.className='eval-auto-result';autoPanel.innerHTML='<strong>🧮 Evaluación interactiva:</strong> responde en pantalla y presiona <em>Calificar prueba</em>. La impresión conserva el formato original sin respuestas digitadas.';out.appendChild(autoPanel);fin('s-evaluacion');}
function toggleEvalAns(){evalAnsVisible=!evalAnsVisible;document.querySelectorAll('#evalOut .eval-answer').forEach(el=>el.style.display=evalAnsVisible?'block':'none');sfx('click');}
function normalizeEvalAnswer(v){return(v||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').replace(/[()]/g,'').trim();}
function isCpCorrect(student,expected){const s=normalizeEvalAnswer(student);const e=normalizeEvalAnswer(expected);if(!s)return false;const variants=new Set([e]);if(e.includes(' '))e.split(' ').forEach(x=>x&&variants.add(x));return variants.has(s)||e.replace(/[^a-z0-9]/g,'')===s.replace(/[^a-z0-9]/g,'');}
function setEvalFeedback(id,ok,msg){const el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='eval-item-feedback '+(ok?'eval-ok':'eval-no');}
function gradeEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const d=window._evalPrintData;let total=0;const detail={cp:0,tf:0,mc:0,pr:0};d.cp.forEach((it,i)=>{const input=document.querySelector(`[data-cp="${i}"]`);const ok=isCpCorrect(input?input.value:'',it.a);if(input){input.classList.toggle('eval-input-ok',ok);input.classList.toggle('eval-input-no',!ok);}if(ok){detail.cp++;total+=5;}setEvalFeedback('evalFbCp'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.a);});d.tf.forEach((it,i)=>{const selected=document.querySelector(`input[name="tf${i}"]:checked`);const ok=!!selected&&(selected.value==='true')===it.a;if(ok){detail.tf++;total+=5;}setEvalFeedback('evalFbTf'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+(it.a?'Verdadero':'Falso'));});d.mc.forEach((it,i)=>{const selected=document.querySelector(`input[name="mc${i}"]:checked`);const ok=!!selected&&Number(selected.value)===it.a;if(ok){detail.mc++;total+=5;}setEvalFeedback('evalFbMc'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.o[it.a]);});const expectedLetters=d.pr.terms.map(it=>d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)]);expectedLetters.forEach((letter,i)=>{const sel=document.querySelector(`[data-pr="${i}"]`);const ok=!!sel&&sel.value===letter;if(sel){sel.classList.toggle('eval-input-ok',ok);sel.classList.toggle('eval-input-no',!ok);}if(ok){detail.pr++;total+=5;}});const prMsg=`Pareados: ${detail.pr}/5 correctos. ${detail.pr===5?'Excelente. +25 pts':'Clave: '+expectedLetters.map((l,i)=>(i+16)+'→'+l).join(' · ')}`;setEvalFeedback('evalFbPr',detail.pr===5,prMsg);const result=document.getElementById('evalAutoResult');if(result){result.className='eval-auto-result '+(total>=70?'eval-auto-pass':'eval-auto-risk');result.innerHTML=`<strong>Resultado automático: ${total}/100 puntos</strong><br><span>Completar: ${detail.cp*5}/25 · V/F: ${detail.tf*5}/25 · Selección: ${detail.mc*5}/25 · Pareados: ${detail.pr*5}/25</span><br><em>Este resultado es solo para revisión en pantalla; la impresión conserva el formato limpio para papel.</em>`;}if(total>=70){pts(8);showToast('🎯 Evaluación calificada: '+total+'/100');}else showToast('🧮 Evaluación calificada: '+total+'/100. Revisa las respuestas marcadas.');}
function printEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const forma=window._currentEvalForm||1;const d=window._evalPrintData;let s1=`<div class="sec-title"><span>I. Completar el espacio</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.cp.forEach((it,i)=>{const q=it.q.replace('___','<span class="cp-blank"></span>');s1+=`<div class="cp-row"><span class="qn">${i+1}.</span><span class="cp-text">${q}</span></div>`;});let s2=`<div class="sec-title"><span>II. Verdadero o Falso</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.tf.forEach((it,i)=>{s2+=`<div class="tf-row"><span class="qn">${i+6}.</span><span class="tf-blank"></span><span class="tf-text">${it.q}</span></div>`;});let s3=`<div class="sec-title"><span>III. Selección Múltiple</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="mc-grid">`;d.mc.forEach((it,i)=>{const opts=it.o.map((op,oi)=>`<label class="mc-opt"><input type="radio" name="mcp${i}"> ${op}</label>`).join('');s3+=`<div class="mc-item"><div class="mc-q"><span class="qn">${i+11}.</span><span>${it.q}</span></div><div class="mc-opts">${opts}</div></div>`;});s3+=`</div>`;let colL='<div class="pr-col"><div class="pr-head">📌 Términos</div>';d.pr.terms.forEach((it,i)=>{colL+=`<div class="pr-item"><span class="pr-num">${i+16}.</span><span class="pr-line"></span>${it.term}</div>`;});colL+='</div>';let colR='<div class="pr-col"><div class="pr-head">🔑 Definiciones</div>';d.pr.shuffledDefs.forEach((it,i)=>{colR+=`<div class="pr-item"><span class="pr-num">${d.pr.letters[i]}.</span>${it.def}</div>`;});colR+='</div>';let s4=`<div class="pr-section"><div class="sec-title"><span>IV. Términos Pareados</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="pr-grid">${colL}${colR}</div></div>`;let pR='';pR+=`<div class="p-sec"><div class="p-ttl">I. Completar</div><table class="p-tbl">`;d.cp.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+1}.</td><td class="pa">${it.a}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">II. V o F</div><table class="p-tbl">`;d.tf.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+6}.</td><td class="pa">${it.a?'V':'F'}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">III. Selección</div><table class="p-tbl">`;d.mc.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+11}.</td><td class="pa">${it.o[it.a]}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">IV. Pareados</div><table class="p-tbl">`;d.pr.terms.forEach((it,i)=>{const l=d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)];pR+=`<tr><td class="pn">${i+16}.</td><td class="pa">${i+16}→${l}</td></tr>`;});pR+=`</table></div>`;const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Evaluación La voz y el punto de vista · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.12rem 0.4rem;margin:0.22rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3730a3;background:#e0e7ff;color:#3730a3;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3730a3;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:58px;border-bottom:1.5px solid #3730a3;height:12px;}.obt-pct{white-space:nowrap;}.qn{font-weight:700;min-width:22px;flex-shrink:0;}.tf-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.tf-blank{display:inline-block;min-width:40px;border-bottom:1.5px solid #111;flex-shrink:0;margin:0 0.18rem;}.tf-text{flex:1;}.mc-item{border:1px solid #ddd;border-radius:4px;padding:0.14rem 0.35rem;margin-bottom:0.1rem;break-inside:avoid;page-break-inside:avoid;}.mc-q{font-size:10.5pt;line-height:1.3;display:flex;gap:0.28rem;margin-bottom:0.07rem;}.mc-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.1rem 0.5rem;}.mc-opts{display:grid;grid-template-columns:repeat(4,1fr);gap:0.04rem 0.15rem;margin-left:0.8rem;}.mc-opt{font-size:9pt;display:flex;align-items:center;gap:0.15rem;}.mc-opt input{width:10px;height:10px;flex-shrink:0;}.cp-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.cp-text{flex:1;}.cp-blank{display:inline-block;min-width:150px;border-bottom:1.5px solid #111;margin:0 0.12rem;}.pr-section{margin-top:0.1rem;}.pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.08rem 0.4rem;margin-top:0.08rem;}.pr-head{font-size:9pt;font-weight:700;color:#555;margin-bottom:0.1rem;}.pr-item{font-size:10.5pt;padding:0.1rem 0.28rem;background:#e0e7ff;border-radius:3px;margin-bottom:0.07rem;display:flex;align-items:center;gap:0.2rem;line-height:1.2;break-inside:avoid;page-break-inside:avoid;}.pr-num{font-weight:700;color:#3730a3;min-width:19px;flex-shrink:0;}.pr-line{display:inline-block;min-width:19px;border-bottom:1.5px solid #111;margin-right:0.14rem;flex-shrink:0;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.22rem;padding:0.15rem 0;page-break-before:avoid;break-before:avoid;color:#3730a3;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3730a3;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.25rem 0.4rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.15rem;}.p-tbl{width:100%;border-collapse:collapse;font-size:7.5pt;}.p-tbl tr{border-bottom:1px dotted #ddd;}.p-tbl td{padding:0.07rem 0.12rem;vertical-align:top;}.pn{font-weight:700;width:16px;color:#555;}.pa{color:#007a00;font-weight:600;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Final · La voz y el punto de vista · Ruta del Hilo que Tira · Etapa 6</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Instituto:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · Cada respuesta vale 5 puntos</p></div>${s1}${s2}${s3}${s4}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100%</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Evaluación Final · La voz y el punto de vista · Ruta del Hilo que Tira · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 4 secciones × 5 preguntas × 5 pts c/u</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;const win=window.open('','_blank','');if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);}

