function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"EL TESTIMONIO VENDIDO COMO EL REPORTE COMPLETO. Un video de una beca de L 80,000 sube el testimonio de un alumno, en primera persona, y el texto que lo acompaña dice: «así fueron los hechos», como si fuera un reporte neutral de todo el proceso."},{"txt":"EL VIDEO QUE SALTA DE MENTE EN MENTE SIN AVISAR. Un video sobre un aula de 32 alumnos salta, en los primeros quince minutos de clase, de lo que piensa la maestra a lo que piensa un alumno, en el mismo minuto, sin ninguna señal."},{"txt":"LO QUE EL NARRADOR JURA QUE «SENTÍA POR DENTRO». Un informe de un campamento de L 45,000 jura que un niño «sentía miedo por dentro» durante una actividad, sin que el niño lo haya dicho ni que nadie lo confirme."},{"txt":"EL INFORME QUE CONFUNDE TERCERA PERSONA CON NEUTRALIDAD. Un informe de un patrocinio de L 300,000 repite, con el tono de «así fue», la versión de un solo maestro, y alguien lo defiende diciendo que «está en tercera persona, así que es neutral»."},{"txt":"LA HISTORIA DONDE SÍ CONVIENE UNA SOLA MIRADA. La historia de un alumno con becas de L 120,000 a lo largo de dos años se cuenta desde su propia mirada, con su permiso, y sin inventarle pensamientos a nadie más."},{"txt":"EL NARRADOR QUE EXAGERA A PROPÓSITO, Y EL FRENO ÉTICO. Una convocatoria de una feria de M.E.T.A.S se escribe en primera persona con un tono muy exagerado: «la mejor feria de toda la historia de esta casa», con humor claramente marcado."},{"txt":"CUANDO EL ESTILO INDIRECTO LIBRE ACLARA, Y CUANDO CONFUNDE. Un boletín de fin de año, con L 500,000 recaudados, funde en un mismo párrafo la voz de una maestra («¡por fin se pudo techar el aula!») con la cifra oficial, sin comillas."},{"txt":"CIDE HAMETE AL REVÉS. Un informe para un donante de L 200,000 cita el reporte de un proveedor sobre materiales entregados, del que la organización tiene dudas en dos de tres envíos."}];
const critCaseQuestions=["1. Di si el problema de este caso está en LA VOZ (quién habla), LA FOCALIZACIÓN (cuánto sabe) o LA FIABILIDAD (cuánto se le puede creer), y por qué.","2. Aplica la ficha del narrador completa: quién habla, cuánto sabe, cuánto se le puede creer.","3. Aplica una herramienta de la etapa (Genette 1972, Booth 1961, Bal 1985, Stanzel 1979, Bally 1912 o James 1907-1909) con su autor y su año.","4. Escribe la pregunta que decide y la condición con la que el caso quedaría resuelto."];
const critCaseGuides=["Se valora que se identifique con claridad de cuál de las tres casillas viene el problema real del caso, sin mezclar las tres en una sola respuesta vaga.","Se valora que las tres casillas queden llenas con algo concreto del caso, o con la nota honesta de que alguna todavía no se puede llenar.","Se valora que la herramienta elegida encaje con el problema real del caso (un salto de cabeza pide a Stanzel; una fuente dudosa pide al Quijote y a Booth; una mezcla de voces pide a Bally) y que viaje con su autor y su año.","Se valora que la pregunta que decide sea concreta y que la condición diga con claridad qué cambiaría para que el caso quedara resuelto. No se valora cerrar con «suena confiable», que es justo la frase que este caso desmiente."];
const critErrorBank=[{"txt":"«Este informe está en tercera persona, así que es objetivo y sabe todo lo que pasó.»","g1":"Confunde la persona gramatical (la voz) con la focalización: la tercera persona no implica saber más (Genette, 1972, distingue los tres grados).","g2":"Confunde tercera persona con neutralidad: un narrador en tercera persona puede tener una sola fuente y no ser neutral."},{"txt":"«Nunca hay que cambiar de mente narradora dentro de un mismo texto, es una regla que no admite excepción.»","g1":"Trata una regla de taller como ley absoluta, ignorando que la omnisciencia declarada (Stanzel, 1979) mueve de mente en mente a propósito.","g2":"No distingue entre el salto de cabeza descuidado (un error real) y el narrador autorial que declara desde el principio que sabe todo."},{"txt":"«El autor implícito es la opinión personal del autor real, publicada en sus entrevistas.»","g1":"Confunde al autor real con el autor implícito: Booth (1961) los distingue con cuidado; el autor implícito es la imagen que el propio texto proyecta.","g2":"Ignora que el concepto fue reformulado después, por Ansgar Nünning, hacia el lado del lector, no solo del autor implícito."},{"txt":"«Cide Hamete Benengeli fue el verdadero historiador árabe que escribió el Quijote, y Cervantes solo lo tradujo.»","g1":"Toma como hecho real un dispositivo narrativo inventado por Cervantes dentro de la ficción de 1605.","g2":"Ignora que el propio narrador del Quijote desconfía de esa fuente y la llama mentirosa, justo el ejemplo de fiabilidad declarada que enseña esta etapa."},{"txt":"«La focalización la inventó Mieke Bal en 1985, y antes nadie había separado quién ve de quién habla.»","g1":"Le pone un autor equivocado: la focalización es de Gérard Genette (1972).","g2":"Bal (1985) no la inventó, la refinó, distinguiendo el focalizador del focalizado para los casos borrosos que Genette dejaba."},{"txt":"«El estilo indirecto libre son las palabras exactas que el personaje pensó, entre comillas.»","g1":"Confunde el estilo indirecto libre (Bally, 1912) con el estilo directo: el indirecto libre no lleva comillas ni «pensó que».","g2":"No explica su función real: funde la voz del narrador con la mente del personaje, sin marcar dónde empieza una y termina la otra."}];
const critDecisionBank=["El testimonio del alumno de la beca de L 80,000 ya está grabado y el texto dice «así fueron los hechos»: ¿se corrige el rótulo a «testimonio de…», se deja porque ya se publicó, o se elimina el video entero? Di qué harías.","El video del aula de 32 alumnos ya salta de la mente de la maestra a la del alumno sin avisar: ¿se declara desde el inicio un narrador que lo sabe todo, se separan las dos escenas, o se deja como está porque «ya se entiende»? Di el riesgo de cada opción.","El informe del campamento de L 45,000 ya jura que un niño «sentía miedo por dentro»: ¿se corrige a lo observable, se busca la fuente que sí lo sabe, o se deja porque «así se sintió, seguro»? Di qué harías con el tiempo que queda.","El informe del patrocinio de L 300,000 ya repite una sola versión con tono de «así fue»: ¿se contrasta con otra fuente, se publica como está porque el plazo es hoy, o se reescribe borrando toda cifra dudosa? Di qué se pierde con cada opción.","La historia del alumno con L 120,000 en becas durante dos años ya tiene el borrador escrito sin permiso firmado: ¿se pide el permiso antes de publicar, se publica igual porque «ya lo contó de palabra», o se cambia a tercera persona genérica sin nombres? Di la condición con la que sí valdría publicarla.","La convocatoria exagerada de la feria ya está escrita con un tono muy hiperbólico: ¿se deja el tono con los datos reales al lado, se pasa a un tono neutro sin gracia, o se publica sin marcar que exagera? Di qué harías.","El boletín de fin de año con los L 500,000 recaudados ya mezcla la voz de la maestra con la cifra oficial en el mismo párrafo, sin comillas: ¿se separan las dos voces, se deja porque «se entiende igual», o se quita la frase de la maestra? Di qué harías.","El informe del donante de L 200,000 ya repite el reporte del proveedor sobre materiales entregados, del que hay dudas en dos de tres envíos: ¿se declara la duda al citarlo, se repite como hecho porque «el proveedor lo dijo», o se omite esa parte del informe? Di con qué protocolo lo decidirías."];
const critDecisionGuide="La decisión se puntúa por el procedimiento con que se llegó a ella, no por lo audaz que suene. Se valora que se identifique si el problema real está en la voz, en la focalización o en la fiabilidad, y que la herramienta elegida (Genette, Booth, Bal, Stanzel, Bally o James) encaje con el problema real y viaje con su autor y su año. Se valora que la respuesta no se cierre con «suena confiable» ni con «así ya se entiende», que son las dos fórmulas que esta etapa sustituye. Se valora la honradez cuando el caso, tal como está descrito, no permite decidir con los datos que hay: decir «falta este dato» es una respuesta correcta.";
const critCompareBank=[{"a":"«El informe dice: 'así fueron los hechos', y solo cuenta lo que el alumno recuerda.»","b":"«El informe dice: 'este es el testimonio del alumno, en sus propias palabras', y aclara que no se contrastó con otras fuentes.»","ga":"Vende una sola voz en primera persona como el reporte objetivo completo, confundiendo voz con fiabilidad total.","gb":"Declara la voz y el límite de lo que sabe, sin fingir más certeza de la que hay.","gr":"Los dos cuentan la misma beca. La diferencia es si el rótulo declara de quién es la voz, o la disfraza de hecho neutral."},{"a":"«El video salta de lo que piensa la maestra a lo que piensa el alumno, en el mismo minuto, sin ningún aviso.»","b":"«El video declara, desde el inicio, una voz que conoce lo que piensan varios personajes, y así lo sostiene toda la pieza.»","ga":"Es un salto de cabeza descuidado: el espectador no sabe cómo el narrador llegó a saber eso.","gb":"Es omnisciencia declarada (Stanzel, 1979, narrador autorial): el mismo movimiento, pero anunciado.","gr":"Los dos narradores saben lo mismo. La diferencia es si el lector fue avisado de que ese narrador puede saberlo."},{"a":"«El informe del patrocinio repite la versión de un solo maestro, con el tono de 'así fue'.»","b":"«El informe del patrocinio cita al maestro, y aclara que es su versión, contrastada con la de dos alumnos.»","ga":"Focalización interna de una sola fuente, vendida como si fuera focalización cero, que lo sabe todo.","gb":"Declara su fuente y la contrasta, sin fingir saber más de lo que sabe.","gr":"Los dos informes hablan del mismo patrocinio. La diferencia es cuántas fuentes hay detrás, y si se declaran."},{"a":"«El informe del donante repite: 'el proveedor entregó el material completo'.»","b":"«El informe del donante dice: 'según el proveedor, el material se entregó completo; esta organización no pudo verificarlo en dos de los tres envíos'.»","ga":"Repite una fuente de la que hay dudas, sin declarar la duda: fiabilidad no declarada.","gb":"Cita la misma fuente, pero declara la duda, como el narrador del Quijote (1605) con Cide Hamete.","gr":"Los dos informes citan al mismo proveedor. La diferencia es si la desconfianza se dice en voz alta o se esconde."}];
const critCauseBank=[{"cause":"Se presenta un testimonio en primera persona como si fuera el reporte objetivo completo.","guide":"El lector cree que tiene la versión neutral cuando solo tiene una voz, la del testigo de M.E.T.A.S. Se corrige declarando de quién es la voz."},{"cause":"Un narrador en tercera persona salta de la mente de un personaje a la de otro sin ninguna señal.","guide":"El lector pierde el hilo de cómo el narrador sabe lo que sabe: es el salto de cabeza que Stanzel (1979) distingue de la omnisciencia declarada. Se corrige anunciando el cambio o separando las escenas."},{"cause":"Se afirma lo que alguien «sentía por dentro» sin ninguna fuente que lo respalde.","guide":"Se vende focalización externa como si fuera interna. Se corrige describiendo solo lo observable, o citando a quien sí lo sabe."},{"cause":"Se repite el reporte de una fuente de la que hay dudas, sin declarar la duda.","guide":"El informe hereda el problema de su fuente sin avisar al lector. Se corrige citando la fuente y declarando la desconfianza, como el narrador del Quijote (1605) con Cide Hamete."},{"cause":"Se funde la opinión de una persona con una cifra oficial, en el mismo párrafo, sin comillas.","guide":"El estilo indirecto libre (Bally, 1912), mal usado, confunde qué es un hecho verificado y qué es la voz de una persona. Se corrige separando las dos."},{"cause":"Se trata la regla de nunca cambiar de punto de vista como ley absoluta, sin excepción.","guide":"Se prohíbe una herramienta legítima, la omnisciencia declarada, por confundirla con su versión descuidada, el salto de cabeza."}];
const critEffectBank=[{"effect":"El testimonio del alumno se publica como «testimonio de…», no como «así fueron los hechos».","guide":"Se declaró la voz (Genette, 1972) sin fingir que una sola persona cuenta la verdad completa."},{"effect":"El video del aula declara, desde el principio, que su narrador conoce lo que piensan varios personajes.","guide":"Se convirtió un salto de cabeza en omnisciencia declarada (Stanzel, 1979), avisando al espectador."},{"effect":"El informe del campamento describe solo lo observable: «se quedó en silencio, con los brazos cruzados».","guide":"Se corrigió la focalización externa vendida como interna, sin inventar lo que el niño sentía."},{"effect":"El informe del donante declara que no pudo verificar dos de los tres envíos del proveedor.","guide":"Se citó la fuente dudosa declarando la duda, en vez de repetirla como un hecho comprobado."},{"effect":"El boletín separa la cifra oficial de L 500,000 de la frase exacta de la maestra, entre comillas.","guide":"Se corrigió el estilo indirecto libre (Bally, 1912) mal usado, que mezclaba un hecho con una voz."},{"effect":"La convocatoria de la feria deja el tono exagerado, pero con la fecha y el lugar en letra clara al lado.","guide":"Se aplicó el freno ético al narrador no fiable a propósito: el lector puede disfrutar la exageración sin perder el dato real."}];
function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🪪 La ficha del narrador bajo presión · Forma ${cf} · La voz y el punto de vista · Ruta del Hilo que Tira`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El caso sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">Aplica la ficha del narrador a este caso: quién habla, cuánto sabe, cuánto se le puede creer, y qué herramienta (con su autor y su año) usarías.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🪪 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La ficha del narrador bajo presión: '+total+'/100');}
  else showToast('🪪 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El caso sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">Aplica la ficha del narrador a este caso: quién habla, cuánto sabe, cuánto se le puede creer, y qué herramienta (con su autor y su año) usarías.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos aplica bien una herramienta de la etapa, y cuál se queda corto? 2. ¿Qué le falta al otro, y cómo se corrige?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. El caso</div>`+critCaseQuestions.map((q,i)=>`<div class="p-crit-line">${q} ${critCaseGuides[i]}</div>`).join('')+`</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La ficha del narrador bajo presión · La voz y el punto de vista · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3730a3;background:#e0e7ff;color:#3730a3;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3730a3;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3730a3;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#e0e7ff;border-left:3px solid #3730a3;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#e0e7ff;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#e0e7ff;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3730a3;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3730a3;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La ficha del narrador bajo presión · La voz y el punto de vista · Ruta del Hilo que Tira · Etapa 6</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La ficha del narrador bajo presión · La voz y el punto de vista · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1912","icon":"🎭","label":"Bally acuña el estilo indirecto libre","text":"Charles Bally da nombre al recurso que funde la voz del narrador con la mente del personaje, sin comillas ni «pensó que». <strong>Por qué importa aquí:</strong> es la fecha más vieja de la tabla madre, y muestra que separar voces es un problema mucho más viejo que la teoría del siglo veinte."},{"y":"1961","icon":"⚠️","label":"Booth y el narrador no fiable","text":"Wayne Booth publica <strong>«The Rhetoric of Fiction»</strong>, donde acuña el narrador no fiable y el autor implícito: la imagen que el texto proyecta, distinta del autor real. <strong>Por qué importa aquí:</strong> es la tercera casilla de la ficha del narrador, cuánto se le puede creer."},{"y":"1972","icon":"👁️","label":"Genette separa voz y focalización","text":"Gérard Genette publica <strong>«Figures III»</strong>, donde separa quién habla (la voz) de quién ve (la focalización), y propone sus tres grados: cero, interna y externa. <strong>Por qué importa aquí:</strong> es la herramienta central de toda la etapa."},{"y":"1978","icon":"🧠","label":"Premack y Woodruff, la teoría de la mente","text":"David Premack y Guy Woodruff publican <strong>«Does the chimpanzee have a theory of mind?»</strong>, y acuñan el término. <strong>Por qué importa aquí:</strong> explica, desde la psicología, por qué podemos seguir a un narrador que sabe menos que nosotros."},{"y":"1979","icon":"📚","label":"Stanzel y las situaciones narrativas","text":"Franz Stanzel publica <strong>«Theorie des Erzählens»</strong>, con su tipología de narrador autorial, en primera persona, y figural. <strong>Por qué importa aquí:</strong> distingue la omnisciencia declarada del salto de cabeza descuidado."},{"y":"1983","icon":"🔬","label":"Wimmer y Perner, la falsa creencia","text":"Heinz Wimmer y Josef Perner publican la tarea de la falsa creencia, cómo se mide si un niño entiende que otro puede creer algo falso. <strong>Por qué importa aquí:</strong> es el hallazgo replicado que mide la misma capacidad que exige seguir a un narrador limitado."},{"y":"1985","icon":"🔍","label":"Bal refina la focalización","text":"Mieke Bal publica <strong>«Narratología»</strong>, donde distingue el focalizador (quien ve) del focalizado (lo que se ve), refinando los casos borrosos de Genette. <strong>Por qué importa aquí:</strong> es la fila que corrige a otra fila de la propia tabla madre."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: «ESTÁ EN TERCERA PERSONA, ASÍ QUE ES OBJETIVO» ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(sePidioFuente){sfx(sePidioFuente?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(sePidioFuente){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📞</span><span class="ms-text"><strong>Se buscó una segunda fuente:</strong> otro maestro y dos alumnos confirmaron parte de la versión, y el informe salió declarando de quién era cada dato.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪪</span><span class="ms-text"><strong>Quedó apuntada la razón del cambio:</strong> «tercera persona no es lo mismo que fiabilidad», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📤</span><span class="ms-text"><strong>Se publicó tal cual:</strong> el informe salió con el tono de «así fue», y meses después un maestro distinto contó una versión distinta de los mismos hechos.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪪</span><span class="ms-text"><strong>Confundir «tercera persona» con «objetivo»</strong> es exactamente el error que esta etapa señala: lo que vuelve confiable a un narrador no es la persona gramatical con la que habla, es cuánto sabe y con qué se contrastó.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = La voz, paradoja = La focalización,
// utilidad = La fiabilidad, ruina = El estilo indirecto libre.
const parteData={"esperado":{"nombre":"La voz","icon":"🗣️","estructura":{"title":"Qué es","info":"• Quién HABLA: ¿primera, segunda o tercera persona? ¿un personaje de la historia, o una voz de fuera?<br>• Es la primera de las dos preguntas que separa <strong>Gérard Genette, «Figures III» (1972)</strong><br>• El estilo indirecto libre (Bally, 1912) funde esta voz con la del personaje, sin comillas<br>• La voz NO dice, por sí sola, cuánto sabe el narrador"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿en qué persona gramatical habla este narrador?<br>• Se comprueba si el que habla es un personaje de la historia, o una voz externa a ella<br>• Se separa esta pregunta de «cuánto sabe», aunque suelan confundirse<br>• Se anota en la primera casilla de la ficha del narrador"},"enfermedades":{"title":"Dónde se cae","info":"• En confundir la persona gramatical con la fiabilidad o el conocimiento del narrador<br>• En dar por hecho que la tercera persona ya es «objetiva»<br>• En olvidar el año de Genette (1972) al citar la distinción<br>• En mezclar la voz del narrador con la del personaje sin declarar el estilo indirecto libre"},"cuidados":{"title":"En esta casa","info":"• Todo narrador de un video o informe se identifica primero por su voz<br>• Se declara siempre «Genette, 1972» al lado, no «así se cuenta siempre»<br>• Se usa como el primer paso del protocolo, antes de preguntar cuánto sabe<br>• Y se recuerda que la voz es solo la primera de tres casillas"}},"paradoja":{"nombre":"La focalización","icon":"👁️","estructura":{"title":"Qué es","info":"• Cuánto SABE el narrador respecto a los personajes: la segunda pregunta de <strong>Genette (1972)</strong><br>• Tres grados: cero (sabe más), interna (sabe lo mismo), externa (sabe menos, solo lo observable)<br>• <strong>Mieke Bal (1985)</strong> la refina distinguiendo el focalizador del focalizado<br>• Es la que se confunde, por error, con la persona gramatical"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿este narrador sabe más, lo mismo, o menos que los personajes?<br>• Se busca si el narrador entra en la mente de uno, de varios, o de ninguno<br>• Se comprueba si el cambio de mente está declarado (Stanzel, 1979) o es un salto sin aviso<br>• Se anota en la segunda casilla de la ficha del narrador"},"enfermedades":{"title":"Dónde se cae","info":"• En vender focalización externa como si fuera interna, inventando lo que alguien «sentía»<br>• En saltar de mente en mente sin ninguna señal para el lector<br>• En creer que la tercera persona ya implica focalización cero<br>• En citar a Genette sin mencionar el refinamiento de Bal (1985) para los casos borrosos"},"cuidados":{"title":"En esta casa","info":"• Todo video que cambia de mente narradora declara el cambio, o lo separa en escenas<br>• Se declara «Genette, 1972» y, si hace falta el matiz fino, «Bal, 1985»<br>• Se usa como diagnóstico: si algo «sabe» sin explicar cómo, se revisa<br>• Y se recuerda que la focalización cero no es sinónimo de tercera persona"}},"utilidad":{"nombre":"La fiabilidad","icon":"🤝","estructura":{"title":"Qué es","info":"• Cuánto se le puede creer a un narrador: la tercera casilla de la ficha del narrador<br>• <strong>Wayne Booth, «The Rhetoric of Fiction» (1961)</strong>: se mide contra el autor implícito, no contra el autor real<br>• El caso comprobable: <strong>Cide Hamete Benengeli</strong>, la fuente del Quijote (1605) de la que su propio narrador desconfía<br>• Reformulado después por Ansgar Nünning, del lado del lector"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿los valores y la percepción del narrador coinciden con los del autor implícito?<br>• Se busca si hay señales de que se equivoca, miente, o no entiende lo que cuenta<br>• Se comprueba si la fuente dudosa se cita DECLARANDO la duda, o se repite como hecho<br>• Se anota en la tercera casilla, aunque a veces quede pendiente por falta de datos"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que un narrador es fiable solo porque suena seguro de sí mismo<br>• En repetir una fuente dudosa sin declarar la duda<br>• En confundir al autor implícito con el autor real (Booth, 1961, los distingue con cuidado)<br>• En tomar a Cide Hamete Benengeli como un cronista que existió de verdad"},"cuidados":{"title":"En esta casa","info":"• Todo informe con una sola fuente declara que es una sola fuente, sin fingir consenso<br>• Se declara «Booth, 1961» junto al autor implícito, siempre<br>• Se usa el ejemplo de Cide Hamete como el modelo de fiabilidad declarada<br>• Y se recuerda que lo no comprobado se deja pendiente, a la vista"}},"ruina":{"nombre":"El estilo indirecto libre","icon":"🎭","estructura":{"title":"Qué es","info":"• Término acuñado por <strong>Charles Bally (1912)</strong>: funde la voz del narrador con la mente del personaje<br>• No lleva comillas ni «pensó que»: la tercera persona empieza a sonar con las palabras del personaje<br>• Es un recurso de la voz, no una regla ni una ley<br>• Relacionado con la «inteligencia central» de Henry James (1907-1909), el personaje reflector"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿el lector distingue el hecho verificado de la opinión de la persona?<br>• Se busca si hay comillas o marca de estilo directo donde debería haberlas<br>• Se comprueba si el recurso aclara la emoción, o confunde una cifra con una opinión<br>• Se compara con el caso de la maestra del boletín, mezclada sin marca con la cifra oficial"},"enfermedades":{"title":"Dónde se cae","info":"• En fundir un hecho oficial con la opinión de una persona, sin ninguna marca<br>• En confundirlo con el estilo directo, que sí lleva comillas<br>• En usarlo sin saber que se está usando, y perder de vista quién habla<br>• En olvidar su año (1912) y su autor (Bally) al citarlo"},"cuidados":{"title":"En esta casa","info":"• Todo boletín que funde una voz personal con una cifra oficial se revisa y se separa<br>• Se declara «Bally, 1912» cuando se usa a propósito, como recurso, no por accidente<br>• Se usa como diagnóstico: si el lector no sabe quién habla, se marca con comillas<br>• Y se recuerda que es un recurso legítimo, mal usado, no una falla en sí mismo"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={"borges":{"titulo":"El testigo que no supo lo que vio","tipo":"Cuento, a la manera de Jorge Luis Borges"},"cervantes":{"titulo":"El cronista del que no me fío","tipo":"Capítulo, a la manera de Miguel de Cervantes Saavedra"},"harari":{"titulo":"La especie que lee mentes","tipo":"Ensayo, a la manera de Yuval Noah Harari"},"entrevista":{"titulo":"La pregunta que Genette separó en dos","tipo":"Entrevista imaginada con Gérard Genette, a la manera de Joaquín Soler Serrano","ficcion":true},"gala":{"titulo":"A quién se lo cuentas","tipo":"El Loco de la Colina: Jesús Quintero conversa con Carmen Martín Gaite (conversación imaginada)","ficcion":true},"debate":{"titulo":"¿El narrador omnisciente está agotado, o sigue siendo la herramienta más honesta?","tipo":"Careo: las dos posturas de una disputa abierta, con sus réplicas","careo":true}};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · La voz y el punto de vista · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#78350f;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#3730a3;border-bottom:1.5pt solid #3730a3;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #3730a3;background:#e0e7ff;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#78350f;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#3730a3;background:#e0e7ff;border-left:3pt solid #3730a3;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#3730a3;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Storytelling</span><span>👁️ La voz y el punto de vista${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 6 de 12</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 6 de 12</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «La voz y el punto de vista»</h1><div class="tipo">Un cuento, un capítulo, un ensayo, dos entrevistas imaginadas y un careo, sobre el mismo tema</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, el sexto es un careo escrito por la casa sobre una disputa real, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. La entrevista con Gérard Genette y la conversación entre Jesús Quintero y Carmen Martín Gaite son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 6 de 12</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">La voz y el punto de vista · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes ni Harari, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron). El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

