const lectAnalisisBank=[
{q:'¿Por qué Waldo no mintió, según su propio relato, y sin embargo tampoco contó la verdad? Relaciona tu respuesta con la diferencia entre sinceridad y exactitud que el propio cuento propone.',guia:'Se espera que el lector explique que Waldo cree de verdad lo que cuenta, así que no miente a propósito, pero su certeza sobre la culpa de Sabino le impide interpretar correctamente los detalles que él mismo va revelando (la vela, el empalme, la ventana). El cuento distingue entre contar con sinceridad (lo que Waldo cree que vio) y contar con exactitud (lo que de verdad pasó), y muestra que un narrador puede ser honesto en su intención y limitado en su focalización al mismo tiempo, sin que eso lo convierta en un mentiroso.',t:'Borges'},
{q:'Explica qué encuentra Waldo, muchos años después, en un libro sobre teoría narrativa, y por qué esas dos ideas «le devuelven esa noche entera».',guia:'Se espera que el lector explique que Waldo encuentra la distinción de Genette (1972) entre quién cuenta y cuánto sabe el que cuenta, y el concepto de Booth (1961) de un narrador que no miente pero tampoco se puede creer del todo porque su manera de ver el mundo no coincide con lo que de verdad pasó. Esas dos ideas, leídas con nombre y fecha, le permiten a Waldo reconocer su propio caso: fue, sin saberlo, un ejemplo del tipo de narrador que la teoría describe, y solo la lectura tardía le da el vocabulario para entender lo que vivió.',t:'Borges'},
{q:'Compara cómo don Casimiro y Gil Overo comunican lo mismo (que la hazaña del hidalgo es falsa) de dos maneras distintas. ¿Cuál corresponde a una voz insegura de su propia fiabilidad, y cuál a un detalle que se basta solo?',guia:'Se espera que el lector identifique que don Casimiro CUENTA su hazaña con adjetivos superlativos («valentísimo», «nobilísimo») que, cuanto más se repiten, más suenan a una fiabilidad que necesita reforzarse a gritos, mientras que Gil Overo, sin decir una palabra, deja ver un solo detalle concreto (las plumas de gallina) que desarma el relato entero. El efecto es que la voz de don Casimiro pierde fiabilidad cuanto más insiste, mientras que el silencio de Gil, apoyado en un detalle verificable, resulta mucho más creíble sin necesidad de ninguna declaración.',t:'Cervantes'},
{q:'Explica el recurso narrativo que usa el narrador del capítulo al citar la crónica del bachiller Onofre Bercebú, y relaciónalo con lo que hace el propio narrador del Quijote (1605) con Cide Hamete Benengeli.',guia:'Se espera que el lector explique que el narrador del capítulo cita una fuente ajena (la crónica del bachiller Bercebú) mientras va marcando, en el propio texto, los puntos donde no le cree del todo, en vez de repetir la crónica como si fuera un hecho comprobado. Este recurso reproduce, a propósito, el que usa el narrador del Quijote (1605) con Cide Hamete Benengeli: citar la fuente y declarar la desconfianza en la misma página, en vez de fingir una certeza que no existe. Es el mismo mecanismo de fiabilidad declarada que la etapa entera viene a enseñar.',t:'Cervantes'},
{q:'Explica, con tus palabras, qué es la teoría de la mente (Premack y Woodruff, 1978) y por qué el ensayo la relaciona con la capacidad de seguir a un narrador limitado o no fiable.',guia:'Se espera que el lector explique que la teoría de la mente es la capacidad de modelar lo que otra mente sabe, cree o desea, distinto de lo que uno mismo sabe, un término acuñado por Premack y Woodruff en 1978. El ensayo la relaciona con la lectura porque seguir a un narrador que sabe menos que el lector, que se equivoca, o que directamente miente, exige exactamente esa misma maquinaria mental: adivinar qué cree ese narrador que sabe, y si esa creencia coincide con lo que de verdad pasó, tal como un niño adivina dónde va a buscar un objeto alguien que no vio que lo cambiaron de lugar.',t:'Harari'},
{q:'El ensayo presenta juntos el hallazgo de Kidd y Castano (2013) y la réplica fallida de Panero y colegas (2016). Explica por qué esta casa exige presentarlos siempre juntos, y qué lección deja esa manera de citarlos.',guia:'Se espera que el lector explique que Kidd y Castano publicaron en Science, en 2013, que leer ficción literaria mejora la teoría de la mente, un hallazgo que se volvió muy citado, pero que en 2016 un equipo encabezado por Maria Panero no logró replicarlo con una muestra más amplia. Presentarlos siempre juntos evita inflar un hallazgo llamativo sin su contraparte honesta, y deja la lección de que una afirmación popular sobre el poder de la ficción merece el mismo cuidado de cita, fecha y límite que cualquier otra herramienta de esta materia.',t:'Harari'},
{q:'En la entrevista, Genette admite que su propio sistema de los tres grados de focalización tiene «fronteras borrosas», y que Mieke Bal lo refinó en 1985. Explica por qué esa admisión es coherente con la regla de oro de esta materia, en vez de debilitar la herramienta.',guia:'Se espera que el lector explique que la regla de oro de esta materia exige declarar el límite de cada herramienta, no solo su aporte, y que la propia entrevista hace exactamente eso: Genette (1972) reconoce que su taxonomía deja casos borrosos, y cita con nombre y año a quien lo corrigió, Mieke Bal (1985). Esa honestidad no debilita la herramienta: la vuelve más confiable, porque muestra que la teoría literaria se revisa a sí misma en vez de presentarse como una verdad cerrada, el mismo espíritu que exige la ficha del narrador de esta etapa.',t:'Entrevista'},
{q:'Explica la diferencia que Genette establece, en la entrevista, entre la focalización y la persona gramatical, con el ejemplo que él mismo pone de un narrador en tercera persona que «sabe tan poco como el personaje mismo».',guia:'Se espera que el lector explique que Genette distingue con cuidado la persona gramatical (la voz, quién habla) de la focalización (cuánto sabe el narrador), y pone el ejemplo de un narrador en tercera persona con focalización interna, que sabe exactamente lo mismo que el personaje al que sigue, sin ninguna omnisciencia. El ejemplo desarma directamente la confusión de que «tercera persona» es sinónimo de «lo sabe todo»: la persona gramatical no dice, por sí sola, nada sobre cuánto sabe el narrador que la usa.',t:'Entrevista'},
{q:'Explica qué quiere decir Martín Gaite cuando afirma que «toda voz necesita a alguien a quien contarle, y esa persona que escucha cambia lo que se cuenta». Relaciónalo con el ejemplo de «El cuarto de atrás» (1978).',guia:'Se espera que el lector explique que, para Martín Gaite, un narrador no decide solo qué sabe, sino cuánto de eso le entrega a quien lo escucha, y esa decisión ya es parte del punto de vista, no solo de los hechos que se cuentan. El ejemplo de «El cuarto de atrás» (1978), donde el lector no sabe si el hombre desconocido es real o un sueño, muestra que esa incertidumbre no se oculta por capricho, sino porque refleja lo que la propia protagonista podía saber en ese momento: la focalización se ajusta a los límites del personaje, no a la conveniencia del autor.',t:'Quintero y Martín Gaite'},
{q:'Explica por qué Martín Gaite dice que «un narrador honesto no es el que lo cuenta todo», y cómo esa idea se conecta con la tercera casilla de la ficha del narrador de esta etapa.',guia:'Se espera que el lector explique que Martín Gaite separa la honestidad narrativa de la cantidad de información revelada: un narrador puede ocultar mucho y seguir siendo fiable, siempre que no finja saber más de lo que sabe, ni finja ignorar lo que sí sabe. Esta idea se conecta directamente con la tercera casilla de la ficha del narrador, cuánto se le puede creer, porque muestra que la fiabilidad no depende de contarlo todo, sino de que lo que se cuenta y lo que se calla coincidan con lo que ese narrador de verdad puede saber, sin engañar al lector sobre esos límites.',t:'Quintero y Martín Gaite'},
{q:'Explica la disputa central del careo entre la defensa y la objeción del narrador omnisciente, y por qué la moderación dice que el terreno común es más grande de lo que parece.',guia:'Se espera que el lector explique que la defensa sostiene que el narrador omnisciente, declarado desde el inicio (Stanzel, 1979, narrador autorial), es una herramienta honesta y no una trampa, mientras que la objeción, apoyada en James (1907-1909) y Booth (1961), sostiene que la focalización limitada obliga al lector a interpretar por sí mismo y evita que una sola voz imponga un juicio moral disfrazado de verdad universal. El terreno común es más grande de lo esperado porque las dos partes aceptan que el salto de cabeza descuidado es un defecto real, que la fiabilidad no depende de cuánto sabe el narrador sino de si coincide con el autor implícito, y que elegir una focalización es una decisión que debe declararse, no un accidente.',t:'Debate'},
{q:'¿Qué dato concreto propone el careo para acercar la disputa entre el narrador omnisciente y el limitado? ¿Por qué ese dato, y no otro, la resolvería mejor?',guia:'Se espera que el lector identifique que el careo propone estudios con lectores reales que comparen la comprensión y la inmersión de un mismo pasaje contado en focalización cero y en focalización limitada, y que explique por qué ese dato (y no una opinión de crítico o una preferencia de época) resolvería mejor la disputa: porque mediría el efecto real sobre quien recibe el texto, que es justo lo que las dos posturas dicen defender, en vez de quedarse en el terreno de la estética personal o la moda literaria de una década.',t:'Debate'}
];

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue buscando quién habla y quién ve!','¡Muy buen trabajo!','¡Ya distingues la voz de la focalización!','¡Ya sabes cuándo un narrador es fiable!','¡Ninguna fuente se te escapa sin declarar su duda!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='👁️ ¡'+name+' completó la Etapa 6 de la Ruta del Hilo que Tira (La voz y el punto de vista)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

